def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']

    def josephus(n, k):
        """
        Solve Josephus problem: n people in circle, eliminate every k-th person.
        Returns the position of the survivor (0-indexed).
        """
        if n == 1:
            return 0
        else:
            return (josephus(n - 1, k) + k) % n

    # josephus function returns 0-indexed position
    # Convert to 1-indexed as required
    survivor_0indexed = josephus(n, k)
    survivor_1indexed = survivor_0indexed + 1

    return float(survivor_1indexed)
